data["questions"]=allq; data["meta"]["total"]=len(allq); data["meta"]["version"]="1.0"
json.dump(data,open(os.path.join(HERE,"questions.json"),"w"),indent=2,ensure_ascii=False)
print(f"Batch 3 added {len(B)} questions. New total: {len(allq)}")
